function e(e){if(e.sampleSize<25)return .01;let t=Math.max(0,1-e.brierScore/.25),n=Math.max(0,1-e.logLoss/.7),r=Math.max(-.25,Math.min(.25,e.avgClv*4)),i=Math.max(-.25,Math.min(.25,e.roi)),a=Math.min(.3,e.maxDrawdown/Math.max(10,e.sampleSize));return Math.max(.01,.45*t+.25*n+.15*(.5+r)+.15*(.5+i)-a)}function t(t){let n=t.map(t=>({...t,score:e(t.summary)})),r=n.reduce((e,t)=>e+t.score,0)||1;return n.map(e=>({modelName:e.modelName,weight:e.score/r,score:e.score,sampleSize:e.summary.sampleSize}))}export{t};